-- ----------------------------
-- Table structure for config_info
-- ----------------------------
DROP TABLE IF EXISTS `config_info`;
CREATE TABLE `config_info` (
  `ID` bigint NOT NULL,
  `DATA_ID` varchar(1020) NOT NULL,
  `GROUP_ID` varchar(1020) DEFAULT NULL,
  `CONTENT` text NOT NULL,
  `MD5` varchar(128) DEFAULT NULL,
  `GMT_CREATE` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `GMT_MODIFIED` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `SRC_USER` text,
  `SRC_IP` varchar(200) DEFAULT NULL,
  `APP_NAME` varchar(512) DEFAULT NULL,
  `TENANT_ID` varchar(512) DEFAULT '',
  `C_DESC` varchar(1024) DEFAULT NULL,
  `C_USE` varchar(256) DEFAULT NULL,
  `EFFECT` varchar(256) DEFAULT NULL,
  `TYPE` varchar(256) DEFAULT NULL,
  `C_SCHEMA` text,
  `ENCRYPTED_DATA_KEY` text,
  PRIMARY KEY (`ID`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='config_info';

