-- Records of config_info
-- ----------------------------
BEGIN;
INSERT INTO `config_info` (`ID`, `DATA_ID`, `GROUP_ID`, `CONTENT`, `MD5`, `GMT_CREATE`, `GMT_MODIFIED`, `SRC_USER`, `SRC_IP`, `APP_NAME`, `TENANT_ID`, `C_DESC`, `C_USE`, `EFFECT`, `TYPE`, `C_SCHEMA`, `ENCRYPTED_DATA_KEY`) VALUES (1, 'application-dev.yml', 'DEFAULT_GROUP', 'spring:\n  autoconfigure:\n    exclude: com.alibaba.druid.spring.boot.autoconfigure.DruidDataSourceAutoConfigure\n\n# feign 配置\nfeign:\n  sentinel:\n    enabled: true\n  okhttp:\n    enabled: true\n  httpclient:\n    enabled: false\n  client:\n    config:\n      default:\n        connectTimeout: 10000\n        readTimeout: 10000\n  compression:\n    request:\n      enabled: true\n      min-request-size: 8192\n    response:\n      enabled: true\n\n# 暴露监控端点\nmanagement:\n  endpoints:\n    web:\n      exposure:\n        include: \'*\'\n', '9928f41dfb10386ad38b3254af5692e0', '2020-05-20 20:00:00', '2024-08-29 20:14:45', 'nacos', '0:0:0:0:0:0:0:1', '', '', '通用配置', 'null', 'null', 'yaml', '', '');
INSERT INTO `config_info` (`ID`, `DATA_ID`, `GROUP_ID`, `CONTENT`, `MD5`, `GMT_CREATE`, `GMT_MODIFIED`, `SRC_USER`, `SRC_IP`, `APP_NAME`, `TENANT_ID`, `C_DESC`, `C_USE`, `EFFECT`, `TYPE`, `C_SCHEMA`, `ENCRYPTED_DATA_KEY`) VALUES (2, 'xfglpt-gateway-dev.yml', 'DEFAULT_GROUP', 'spring:\n  redis:\n    host: localhost\n    port: 6379\n    password: \n  cloud:\n    gateway:\n      discovery:\n        locator:\n          lowerCaseServiceId: true\n          enabled: true\n      routes:\n        # 认证中心\n        - id: xfglpt-auth\n          uri: lb://xfglpt-auth\n          predicates:\n            - Path=/auth/**\n          filters:\n            # 验证码处理\n            - CacheRequestFilter\n            - ValidateCodeFilter\n            - StripPrefix=1\n        # 代码生成\n        - id: xfglpt-gen\n          uri: lb://xfglpt-gen\n          predicates:\n            - Path=/code/**\n          filters:\n            - StripPrefix=1\n        # 定时任务\n        - id: xfglpt-job\n          uri: lb://xfglpt-job\n          predicates:\n            - Path=/schedule/**\n          filters:\n            - StripPrefix=1\n        # 系统模块\n        - id: xfglpt-system\n          uri: lb://xfglpt-system\n          predicates:\n            - Path=/system/**\n          filters:\n            - StripPrefix=1\n        # 文件服务\n        - id: xfglpt-file\n          uri: lb://xfglpt-file\n          predicates:\n            - Path=/file/**\n          filters:\n            - StripPrefix=1\n\n# 安全配置\nsecurity:\n  # 验证码\n  captcha:\n    enabled: true\n    type: math\n  # 防止XSS攻击\n  xss:\n    enabled: true\n    excludeUrls:\n      - /system/notice\n      - /school/jzbuy/opinions/config\n\n  # 不校验白名单\n  ignore:\n    whites:\n      - /auth/logout\n      - /auth/login\n      - /auth/register\n      - /*/v2/api-docs\n      - /*/v3/api-docs\n      - /csrf\n      - /questionnaireResult/selIpAddress\n\n# springdoc配置\nspringdoc:\n  webjars:\n    # 访问前缀\n    prefix:\n', '51c3addf1c4c05076ec2f339a1fb8d48', '2020-05-14 22:17:55', '2025-05-30 01:13:29', 'nacos', '192.168.1.63', '', '', '网关模块', 'null', 'null', 'yaml', '', '');
INSERT INTO `config_info` (`ID`, `DATA_ID`, `GROUP_ID`, `CONTENT`, `MD5`, `GMT_CREATE`, `GMT_MODIFIED`, `SRC_USER`, `SRC_IP`, `APP_NAME`, `TENANT_ID`, `C_DESC`, `C_USE`, `EFFECT`, `TYPE`, `C_SCHEMA`, `ENCRYPTED_DATA_KEY`) VALUES (3, 'xfglpt-auth-dev.yml', 'DEFAULT_GROUP', 'spring:\n  redis:\n    host: localhost\n    port: 6379\n    password: \n', 'a03e7632a0a74520eeb4fbedd6d82d97', '2020-11-20 08:00:00', '2024-09-02 20:13:58', 'nacos', '0:0:0:0:0:0:0:1', '', '', '认证中心', 'null', 'null', 'yaml', '', '');
INSERT INTO `config_info` (`ID`, `DATA_ID`, `GROUP_ID`, `CONTENT`, `MD5`, `GMT_CREATE`, `GMT_MODIFIED`, `SRC_USER`, `SRC_IP`, `APP_NAME`, `TENANT_ID`, `C_DESC`, `C_USE`, `EFFECT`, `TYPE`, `C_SCHEMA`, `ENCRYPTED_DATA_KEY`) VALUES (4, 'xfglpt-monitor-dev.yml', 'DEFAULT_GROUP', '# spring\nspring:\n  security:\n    user:\n      name: ruoyi\n      password: 123456\n  boot:\n    admin:\n      ui:\n        title: 若依服务状态监控\n', '6f122fd2bfb8d45f858e7d6529a9cd44', '2020-11-20 08:00:00', '2024-08-29 20:15:11', 'nacos', '0:0:0:0:0:0:0:1', '', '', '监控中心', 'null', 'null', 'yaml', '', '');
INSERT INTO `config_info` (`ID`, `DATA_ID`, `GROUP_ID`, `CONTENT`, `MD5`, `GMT_CREATE`, `GMT_MODIFIED`, `SRC_USER`, `SRC_IP`, `APP_NAME`, `TENANT_ID`, `C_DESC`, `C_USE`, `EFFECT`, `TYPE`, `C_SCHEMA`, `ENCRYPTED_DATA_KEY`) VALUES (5, 'xfglpt-system-dev.yml', 'DEFAULT_GROUP', '# spring配置\nspring:\n  redis:\n    host: 192.168.1.56\n    port: 6379\n    password: \n  datasource:\n    druid:\n      stat-view-servlet:\n        enabled: true\n        loginUsername: ruoyi\n        loginPassword: 123456\n    dynamic:\n      druid:\n        initial-size: 5\n        min-idle: 5\n        maxActive: 20\n        maxWait: 60000\n        connectTimeout: 30000\n        socketTimeout: 60000\n        timeBetweenEvictionRunsMillis: 60000\n        minEvictableIdleTimeMillis: 300000\n        validationQuery: SELECT 1 FROM DUAL\n        testWhileIdle: true\n        testOnBorrow: false\n        testOnReturn: false\n        poolPreparedStatements: true\n        maxPoolPreparedStatementPerConnectionSize: 20\n        filters: stat,slf4j\n        connectionProperties: druid.stat.mergeSql\\=true;druid.stat.slowSqlMillis\\=5000\n      datasource:\n          # 主库数据源\n          master:\n            driver-class-name: com.mysql.cj.jdbc.Driver\n            url: jdbc:mysql://localhost:3306/ry-cloud?useUnicode=true&characterEncoding=utf8&zeroDateTimeBehavior=convertToNull&useSSL=true&serverTimezone=GMT%2B8\n            username: root\n            password: password\n          # 从库数据源\n          # slave:\n            # username: \n            # password: \n            # url: \n            # driver-class-name: \n\n# mybatis配置\nmybatis:\n    # 搜索指定包别名\n    typeAliasesPackage: com.xfgl.system\n    # 配置mapper的扫描，找到所有的mapper.xml映射文件\n    mapperLocations: classpath:mapper/**/*.xml\n\n# springdoc配置\nspringdoc:\n  gatewayUrl: http://localhost:8080/${spring.application.name}\n  api-docs:\n    # 是否开启接口文档\n    enabled: true\n  info:\n    # 标题\n    title: \'系统模块接口文档\'\n    # 描述\n    description: \'系统模块接口描述\'\n    # 作者信息\n    contact:\n      name: RuoYi\n      url: https://ruoyi.vip\n', '99444ac8c656e9d23764e36eece4eea9', '2020-11-20 08:00:00', '2025-03-25 00:31:17', NULL, '172.16.100.19', '', '', '系统模块', 'null', 'null', 'yaml', '', '');
INSERT INTO `config_info` (`ID`, `DATA_ID`, `GROUP_ID`, `CONTENT`, `MD5`, `GMT_CREATE`, `GMT_MODIFIED`, `SRC_USER`, `SRC_IP`, `APP_NAME`, `TENANT_ID`, `C_DESC`, `C_USE`, `EFFECT`, `TYPE`, `C_SCHEMA`, `ENCRYPTED_DATA_KEY`) VALUES (6, 'xfglpt-gen-dev.yml', 'DEFAULT_GROUP', '# spring配置\nspring:\n  redis:\n    host: localhost\n    port: 6379\n    password: \n  datasource:\n    driver-class-name: com.mysql.cj.jdbc.Driver\n    url: jdbc:mysql://localhost:3306/ry-cloud?useUnicode=true&characterEncoding=utf8&zeroDateTimeBehavior=convertToNull&useSSL=true&serverTimezone=GMT%2B8\n    username: root\n    password: password\n\n# mybatis配置\nmybatis:\n    # 搜索指定包别名\n    typeAliasesPackage: com.xfgl.gen.domain\n    # 配置mapper的扫描，找到所有的mapper.xml映射文件\n    mapperLocations: classpath:mapper/**/*.xml\n\n# springdoc配置\nspringdoc:\n  gatewayUrl: http://localhost:8080/${spring.application.name}\n  api-docs:\n    # 是否开启接口文档\n    enabled: true\n  info:\n    # 标题\n    title: \'代码生成接口文档\'\n    # 描述\n    description: \'代码生成接口描述\'\n    # 作者信息\n    contact:\n      name: RuoYi\n      url: https://ruoyi.vip\n\n# 代码生成\ngen:\n  # 作者\n  author: ruoyi\n  # 默认生成包路径 system 需改成自己的模块名称 如 system monitor tool\n  packageName: com.xfgl.system\n  # 自动去除表前缀，默认是false\n  autoRemovePre: false\n  # 表前缀（生成类名不会包含表前缀，多个用逗号分隔）\n  tablePrefix: sys_\n', '14d41dda290bf445b7ed06c5667e8e88', '2020-11-20 08:00:00', '2024-09-02 20:14:48', 'nacos', '0:0:0:0:0:0:0:1', '', '', '代码生成', 'null', 'null', 'yaml', '', '');
INSERT INTO `config_info` (`ID`, `DATA_ID`, `GROUP_ID`, `CONTENT`, `MD5`, `GMT_CREATE`, `GMT_MODIFIED`, `SRC_USER`, `SRC_IP`, `APP_NAME`, `TENANT_ID`, `C_DESC`, `C_USE`, `EFFECT`, `TYPE`, `C_SCHEMA`, `ENCRYPTED_DATA_KEY`) VALUES (7, 'xfglpt-job-dev.yml', 'DEFAULT_GROUP', '# spring配置\nspring:\n  redis:\n    host: localhost\n    port: 6379\n    password: \n  datasource:\n    driver-class-name: com.mysql.cj.jdbc.Driver\n    url: jdbc:mysql://localhost:3306/ry-cloud?useUnicode=true&characterEncoding=utf8&zeroDateTimeBehavior=convertToNull&useSSL=true&serverTimezone=GMT%2B8\n    username: root\n    password: password\n\n# mybatis配置\nmybatis:\n    # 搜索指定包别名\n    typeAliasesPackage: com.xfgl.job.domain\n    # 配置mapper的扫描，找到所有的mapper.xml映射文件\n    mapperLocations: classpath:mapper/**/*.xml\n\n# springdoc配置\nspringdoc:\n  gatewayUrl: http://localhost:8080/${spring.application.name}\n  api-docs:\n    # 是否开启接口文档\n    enabled: true\n  info:\n    # 标题\n    title: \'定时任务接口文档\'\n    # 描述\n    description: \'定时任务接口描述\'\n    # 作者信息\n    contact:\n      name: RuoYi\n      url: https://ruoyi.vip\n', 'f78483f845777335b9ed4a9f84758848', '2020-11-20 08:00:00', '2024-09-02 20:14:56', 'nacos', '0:0:0:0:0:0:0:1', '', '', '定时任务', 'null', 'null', 'yaml', '', '');
INSERT INTO `config_info` (`ID`, `DATA_ID`, `GROUP_ID`, `CONTENT`, `MD5`, `GMT_CREATE`, `GMT_MODIFIED`, `SRC_USER`, `SRC_IP`, `APP_NAME`, `TENANT_ID`, `C_DESC`, `C_USE`, `EFFECT`, `TYPE`, `C_SCHEMA`, `ENCRYPTED_DATA_KEY`) VALUES (8, 'xfglpt-file-dev.yml', 'DEFAULT_GROUP', '# 本地文件上传    \r\nfile:\r\n    domain: http://127.0.0.1:9300\r\n    path: D:/ruoyi/uploadPath\r\n    prefix: /statics\r\n\r\n# FastDFS配置\r\nfdfs:\r\n  domain: http://8.129.231.12\r\n  soTimeout: 3000\r\n  connectTimeout: 2000\r\n  trackerList: 8.129.231.12:22122\r\n\r\n# Minio配置\r\nminio:\r\n  url: http://8.129.231.12:9000\r\n  accessKey: minioadmin\r\n  secretKey: minioadmin\r\n  bucketName: test', '5382b93f3d8059d6068c0501fdd41195', '2020-11-20 08:00:00', '2020-12-22 05:01:59', NULL, '0:0:0:0:0:0:0:1', '', '', '文件服务', 'null', 'null', 'yaml', NULL, '');
INSERT INTO `config_info` (`ID`, `DATA_ID`, `GROUP_ID`, `CONTENT`, `MD5`, `GMT_CREATE`, `GMT_MODIFIED`, `SRC_USER`, `SRC_IP`, `APP_NAME`, `TENANT_ID`, `C_DESC`, `C_USE`, `EFFECT`, `TYPE`, `C_SCHEMA`, `ENCRYPTED_DATA_KEY`) VALUES (9, 'sentinel-xfglpt-gateway', 'DEFAULT_GROUP', '[\n    {\n        \"resource\": \"xfglpt-auth\",\n        \"count\": 500,\n        \"grade\": 1,\n        \"limitApp\": \"default\",\n        \"strategy\": 0,\n        \"controlBehavior\": 0\n    },\n	{\n        \"resource\": \"xfglpt-system\",\n        \"count\": 10000,\n        \"grade\": 1,\n        \"limitApp\": \"default\",\n        \"strategy\": 0,\n        \"controlBehavior\": 0\n    },\n	{\n        \"resource\": \"xfglpt-gen\",\n        \"count\": 200,\n        \"grade\": 1,\n        \"limitApp\": \"default\",\n        \"strategy\": 0,\n        \"controlBehavior\": 0\n    },\n	{\n        \"resource\": \"xfglpt-job\",\n        \"count\": 300,\n        \"grade\": 1,\n        \"limitApp\": \"default\",\n        \"strategy\": 0,\n        \"controlBehavior\": 0\n    }\n]', '59c587bf3737bc4a63d1e2073e8586af', '2020-11-20 08:00:00', '2025-03-29 18:03:50', 'nacos', '192.168.1.63', '', '', '限流策略', 'null', 'null', 'json', '', '');
INSERT INTO `config_info` (`ID`, `DATA_ID`, `GROUP_ID`, `CONTENT`, `MD5`, `GMT_CREATE`, `GMT_MODIFIED`, `SRC_USER`, `SRC_IP`, `APP_NAME`, `TENANT_ID`, `C_DESC`, `C_USE`, `EFFECT`, `TYPE`, `C_SCHEMA`, `ENCRYPTED_DATA_KEY`) VALUES (10, 'application-dev.yml', 'DEFAULT_GROUP', 'spring:\n  autoconfigure:\n    exclude: com.alibaba.druid.spring.boot.autoconfigure.DruidDataSourceAutoConfigure\n  servlet:\n    multipart:\n      max-file-size: 2000MB  # 单个文件最大大小\n      max-request-size: 2000MB  # 单次请求最大大小\n      enabled: true  # 启用文件上传\n# feign 配置\nfeign:\n  sentinel:\n    enabled: true\n  okhttp:\n    enabled: true\n  httpclient:\n    enabled: false\n  client:\n    config:\n      default:\n        connectTimeout: 10000\n        readTimeout: 10000\n  compression:\n    request:\n      enabled: true\n      min-request-size: 8192\n    response:\n      enabled: true\n\n# 暴露监控端点\nmanagement:\n  endpoints:\n    web:\n      exposure:\n        include: \'*\'\n\n# MyBatis Plus配置\nmybatis-plus:\n  # 不支持多包, 如有需要可在注解配置 或 提升扫包等级\n  mapperPackage: com.xfgl.**.*\n  # 对应的 XML 文件位置\n  mapperLocations: classpath*:mapper/**/*Mapper.xml\n  # 实体扫描，多个package用逗号或者分号分隔\n  typeAliasesPackage: com.xfgl.**.domain        \n  configuration:\n    # 自动驼峰命名规则（camel case）映射\n    mapUnderscoreToCamelCase: true\n    log-impl: org.apache.ibatis.logging.stdout.StdOutImpl\n    # 更详细的日志输出 会有性能损耗 org.apache.ibatis.logging.stdout.StdOutImpl\n    # 默认日志输出 org.apache.ibatis.logging.slf4j.Slf4jImpl\n  #    logImpl: org.apache.ibatis.logging.stdout.StdOutImpl\n  global-config:\n    # 是否打印 Logo banner\n    banner: false\n    dbConfig:\n      # 主键类型\n      # AUTO 自增 NONE 空 INPUT 用户输入 ASSIGN_ID 雪花 ASSIGN_UUID 唯一 UUID\n      idType: AUTO\n      logic-delete-field: delFlag # 全局逻辑删除的实体字段名\n      logic-delete-value: 1 # 逻辑已删除值(默认为 1)\n      logic-not-delete-value: 0 # 逻辑未删除值(默认为 0)\n', '9a2b3392cfb57974abb42b0ce2dcb93d', '2025-03-25 00:33:33', '2025-06-04 19:04:32', 'nacos', '192.168.1.63', '', '5e3e155d-73b2-4a36-ab8b-e54454e8b351', '通用配置', '', '', 'yaml', '', '');
INSERT INTO `config_info` (`ID`, `DATA_ID`, `GROUP_ID`, `CONTENT`, `MD5`, `GMT_CREATE`, `GMT_MODIFIED`, `SRC_USER`, `SRC_IP`, `APP_NAME`, `TENANT_ID`, `C_DESC`, `C_USE`, `EFFECT`, `TYPE`, `C_SCHEMA`, `ENCRYPTED_DATA_KEY`) VALUES (11, 'xfglpt-gateway-dev.yml', 'DEFAULT_GROUP', 'spring:\n  redis:\n    host: localhost\n    port: 6379\n    password: \n  cloud:\n    gateway:\n      tongweb:\n        httpclient:\n          connect-timeout: 45000\n          response-timeout: 45000s\n      discovery:\n        locator:\n          lowerCaseServiceId: true\n          enabled: true\n      routes:\n        # 认证中心\n        - id: xfglpt-auth\n          uri: lb://xfglpt-auth\n          predicates:\n            - Path=/auth/**\n          filters:\n            # 验证码处理\n            - CacheRequestFilter\n            - ValidateCodeFilter\n            - StripPrefix=1\n        # 代码生成\n        - id: xfglpt-gen\n          uri: lb://xfglpt-gen\n          predicates:\n            - Path=/code/**\n          filters:\n            - StripPrefix=1\n        # 定时任务\n        - id: xfglpt-job\n          uri: lb://xfglpt-job\n          predicates:\n            - Path=/schedule/**\n          filters:\n            - StripPrefix=1\n        # 系统模块\n        - id: xfglpt-system\n          uri: lb://xfglpt-system\n          predicates:\n            - Path=/system/**\n          filters:\n            - StripPrefix=1\n        # 文件服务\n        - id: xfglpt-file\n          uri: lb://xfglpt-file\n          predicates:\n            - Path=/file/**\n          filters:\n            - StripPrefix=1\n        # 学校服务\n        - id: xfglpt-school\n          uri: lb://xfglpt-school\n          predicates:\n            - Path=/school/**\n          filters:\n            - StripPrefix=1\n        # 学校服务\n        - id: xfglpt-supplier\n          uri: lb://xfglpt-supplier\n          predicates:\n            - Path=/supplier/**\n          filters:\n            - StripPrefix=1\n      globalcors:\n        corsConfigurations:\n          \'[/**]\':\n            allowedOriginPatterns: \"*\"\n            allowed-methods: \"*\"\n            allowed-headers: \"*\"\n            allow-credentials: true\n            exposedHeaders: \"Content-Disposition,Content-Type,Cache-Control\"\n\n\n\n# 安全配置\nsecurity:\n  # 验证码\n  captcha:\n    enabled: true\n    type: math\n  # 防止XSS攻击\n  xss:\n    enabled: true\n    excludeUrls:\n      - /system/notice\n      - /school/jzbuy/opinions/config\n      - /system/xfptnotice/**\n      - /school/jzbuy/opinions\n  # 不校验白名单\n  ignore:\n    whites:\n      - /auth/logout\n      - /auth/login\n      - /auth/register\n      - /*/v2/api-docs\n      - /*/v3/api-docs\n      - /csrf\n      - /system/open/**\n      - /school/question/config/content\n      - /school/questionnaireResult\n      - /school/questionnaireResult/selIpAddress\n      - /system/dict/data/type/**\n      - /school/school/open/**\n      - /school/team/meeting/importUserName\n      - /school/question/config/selectName\n      - /school/questionnaireSurvey/exportResultExcel\n      - /school/simOpen/redirecturi\n      - /system/sms/test\n      - /system/sms/sendSms\n      - /system/sms/smsLogin\n      - /system/user/resetPwdSendSms\n      - /system/sms/userEncrypt\n      - /school/suppliceContractSon/dateEnc\n      - /system/getRandom\n      - /system/verifyCertAndSign\n      - /school/**\n      - /system/dict/**\n# springdoc配置\nspringdoc:\n  webjars:\n    # 访问前缀\n    prefix:\n', 'dd5df7d354620ea40627d986b4997a37', '2025-03-25 00:33:33', '2026-04-18 14:19:36', 'nacos', '192.168.1.110', '', '5e3e155d-73b2-4a36-ab8b-e54454e8b351', '网关模块', '', '', 'yaml', '', '');
