INSERT INTO `config_info` (`ID`, `DATA_ID`, `GROUP_ID`, `CONTENT`, `MD5`, `GMT_CREATE`, `GMT_MODIFIED`, `SRC_USER`, `SRC_IP`, `APP_NAME`, `TENANT_ID`, `C_DESC`, `C_USE`, `EFFECT`, `TYPE`, `C_SCHEMA`, `ENCRYPTED_DATA_KEY`) VALUES (14, 'xfglpt-system-dev.yml', 'DEFAULT_GROUP', '# spring配置\nspring:\n  redis:\n    host: localhost\n    port: 6379\n    password: \n  datasource:\n    druid:\n      stat-view-servlet:\n        enabled: true\n        loginUsername: yinet!@#\n        loginPassword: 12dfsol21,fe,lef!\n    dynamic:\n      druid:\n        initial-size: 5\n        min-idle: 5\n        maxActive: 20\n        maxWait: 60000\n        connectTimeout: 30000\n        socketTimeout: 60000\n        timeBetweenEvictionRunsMillis: 60000\n        minEvictableIdleTimeMillis: 300000\n        validationQuery: SELECT 1 FROM DUAL\n        testWhileIdle: true\n        testOnBorrow: false\n        testOnReturn: false\n        poolPreparedStatements: true\n        maxPoolPreparedStatementPerConnectionSize: 20\n        filters: stat,slf4j\n        connectionProperties: druid.stat.mergeSql\\=true;druid.stat.slowSqlMillis\\=5000\n      datasource:\n          # 主库数据源\n        master:\n          driver-class-name: com.mysql.cj.jdbc.Driver\n          url: jdbc:mysql://192.168.1.63:3306/xfglpt?useUnicode=true&characterEncoding=utf8&zeroDateTimeBehavior=convertToNull&useSSL=true&serverTimezone=GMT%2B8\n          username: root\n          password: root\n          # slave:\n            # username: \n            # password: \n            # url: \n            # driver-class-name: \n\n\n# springdoc配置\nspringdoc:\n  gatewayUrl: http://localhost:8080/${spring.application.name}\n  api-docs:\n    # 是否开启接口文档\n    enabled: true\n  info:\n    # 标题\n    title: \'系统模块接口文档\'\n    # 描述\n    description: \'系统模块接口描述\'\n    # 作者信息\n    contact:\n      name: RuoYi\n      url: https://ruoyi.vip\nsms:\n  url: http://10.24.157.187:8095/api/json_message_sendOnlyMessage/v1\n  appcode: fK8w4KIe27Ja\n  appSecret: U14t2Bf98jvZwQlmsR2M3BpRLeN247Se\n  templateId: 520\nmp:\n  ip: https://cloud.hebca.com\n  keyId: 9\n  clientId: hebca_test\n  clientSecret: hebca@2024', 'd3497bd8d284dd27df730754381335f7', '2025-03-25 00:33:33', '2026-04-22 13:56:14', NULL, '0:0:0:0:0:0:0:1', '', '5e3e155d-73b2-4a36-ab8b-e54454e8b351', '系统模块', '', '', 'yaml', '', '');
INSERT INTO `config_info` (`ID`, `DATA_ID`, `GROUP_ID`, `CONTENT`, `MD5`, `GMT_CREATE`, `GMT_MODIFIED`, `SRC_USER`, `SRC_IP`, `APP_NAME`, `TENANT_ID`, `C_DESC`, `C_USE`, `EFFECT`, `TYPE`, `C_SCHEMA`, `ENCRYPTED_DATA_KEY`) VALUES (15, 'xfglpt-gen-dev.yml', 'DEFAULT_GROUP', '# spring配置\nspring:\n  redis:\n    host: 192.168.1.17\n    port: 6379\n    password: \n  datasource:\n    driver-class-name: dm.jdbc.driver.DmDriver\n    url: jdbc:dm://192.168.1.63:5236?schema=XFGLPT&nullCatalogMeansCurrent=true&compatibleMode=oracle\n    username: SYSDBA\n    password: Admin123\n\n\n\n# springdoc配置\nspringdoc:\n  gatewayUrl: http://localhost:8080/${spring.application.name}\n  api-docs:\n    # 是否开启接口文档\n    enabled: true\n  info:\n    # 标题\n    title: \'代码生成接口文档\'\n    # 描述\n    description: \'代码生成接口描述\'\n    # 作者信息\n    contact:\n      name: RuoYi\n      url: https://ruoyi.vip\n\n# 代码生成\ngen:\n  # 作者\n  author: yinet\n  # 默认生成包路径 system 需改成自己的模块名称 如 system monitor tool\n  packageName: com.xfgl.system\n  # 自动去除表前缀，默认是false\n  autoRemovePre: false\n  # 表前缀（生成类名不会包含表前缀，多个用逗号分隔）\n  tablePrefix: sys_\n', '3b5c00b8c80eadb8c529d0954fb33d41', '2025-03-25 00:33:33', '2025-10-22 13:28:03', 'nacos', '192.168.1.111', '', '5e3e155d-73b2-4a36-ab8b-e54454e8b351', '', '', '', 'yaml', '', '');
INSERT INTO `config_info` (`ID`, `DATA_ID`, `GROUP_ID`, `CONTENT`, `MD5`, `GMT_CREATE`, `GMT_MODIFIED`, `SRC_USER`, `SRC_IP`, `APP_NAME`, `TENANT_ID`, `C_DESC`, `C_USE`, `EFFECT`, `TYPE`, `C_SCHEMA`, `ENCRYPTED_DATA_KEY`) VALUES (16, 'xfglpt-job-dev.yml', 'DEFAULT_GROUP', '# spring配置\nspring:\n  redis:\n    host: 192.168.1.17\n    port: 6379\n    password: \n  datasource:\n    druid:\n      stat-view-servlet:\n        enabled: true\n        loginUsername: yinet!@#\n        loginPassword: 12dfsol21,fe,lef!\n    dynamic:\n      druid:\n        initial-size: 5\n        min-idle: 5\n        maxActive: 20\n        maxWait: 60000\n        connectTimeout: 30000\n        socketTimeout: 60000\n        timeBetweenEvictionRunsMillis: 60000\n        minEvictableIdleTimeMillis: 300000\n        validationQuery: SELECT 1 FROM DUAL\n        testWhileIdle: true\n        testOnBorrow: false\n        testOnReturn: false\n        poolPreparedStatements: true\n        maxPoolPreparedStatementPerConnectionSize: 20\n        filters: stat,slf4j\n        connectionProperties: druid.stat.mergeSql\\=true;druid.stat.slowSqlMillis\\=5000\n      datasource:\n          # 主库数据源\n          # 主库数据源\n          master:\n            url: jdbc:kingbase8://192.168.1.63:54321/xf?currentSchema=xfglpt,sys_catalog\n            username: system\n            password: system\n            driver-class-name: com.kingbase8.Driver\n            connection-init-sql: SET search_path TO xfglpt;\n          # 从库数据源\n          # slave:\n            # username: \n            # password: \n            # url: \n            # driver-class-name: \n\n# mybatis配置\nmybatis:\n    # 搜索指定包别名\n    typeAliasesPackage: com.xfgl.job.domain\n    # 配置mapper的扫描，找到所有的mapper.xml映射文件\n    mapperLocations: classpath:mapper/**/*.xml\n\n# springdoc配置\nspringdoc:\n  gatewayUrl: http://localhost:8080/${spring.application.name}\n  api-docs:\n    # 是否开启接口文档\n    enabled: true\n  info:\n    # 标题\n    title: \'定时任务接口文档\'\n    # 描述\n    description: \'定时任务接口描述\'\n    # 作者信息\n    contact:\n      name: RuoYi\n      url: https://ruoyi.vip\n', '76f60c65026bfe64d43a355c7498558a', '2025-03-25 00:33:33', '2025-09-15 13:43:03', 'nacos', '192.168.1.88', '', '5e3e155d-73b2-4a36-ab8b-e54454e8b351', '定时任务', '', '', 'yaml', '', '');
INSERT INTO `config_info` (`ID`, `DATA_ID`, `GROUP_ID`, `CONTENT`, `MD5`, `GMT_CREATE`, `GMT_MODIFIED`, `SRC_USER`, `SRC_IP`, `APP_NAME`, `TENANT_ID`, `C_DESC`, `C_USE`, `EFFECT`, `TYPE`, `C_SCHEMA`, `ENCRYPTED_DATA_KEY`) VALUES (17, 'xfglpt-file-dev.yml', 'DEFAULT_GROUP', '# 本地文件上传    \nfile:\n    domain: http://192.168.1.110:9300\n    path: /Library/dev/ruoyi/uploadPath\n    prefix: /filestatics\n\n# FastDFS配置\nfdfs:\n  domain: http://8.129.231.12\n  soTimeout: 3000\n  connectTimeout: 2000\n  trackerList: 8.129.231.12:22122\n\n# Minio配置\nminio:\n  url: http://8.129.231.12:9000\n  accessKey: minioadmin\n  secretKey: minioadmin\n  bucketName: test', '206b991006707aaf64c66b3482d4125d', '2025-03-25 00:33:33', '2026-04-14 13:22:15', 'nacos', '192.168.1.110', '', '5e3e155d-73b2-4a36-ab8b-e54454e8b351', '文件服务', '', '', 'yaml', '', '');
INSERT INTO `config_info` (`ID`, `DATA_ID`, `GROUP_ID`, `CONTENT`, `MD5`, `GMT_CREATE`, `GMT_MODIFIED`, `SRC_USER`, `SRC_IP`, `APP_NAME`, `TENANT_ID`, `C_DESC`, `C_USE`, `EFFECT`, `TYPE`, `C_SCHEMA`, `ENCRYPTED_DATA_KEY`) VALUES (18, 'sentinel-xfglpt-gateway', 'DEFAULT_GROUP', '[\n    {\n        \"resource\": \"xfglpt-auth\",\n        \"count\": 500,\n        \"grade\": 1,\n        \"limitApp\": \"default\",\n        \"strategy\": 0,\n        \"controlBehavior\": 0\n    },\n	{\n        \"resource\": \"xfglpt-system\",\n        \"count\": 1000,\n        \"grade\": 1,\n        \"limitApp\": \"default\",\n        \"strategy\": 0,\n        \"controlBehavior\": 0\n    },\n	{\n        \"resource\": \"xfglpt-gen\",\n        \"count\": 200,\n        \"grade\": 1,\n        \"limitApp\": \"default\",\n        \"strategy\": 0,\n        \"controlBehavior\": 0\n    },\n	{\n        \"resource\": \"xfglpt-job\",\n        \"count\": 300,\n        \"grade\": 1,\n        \"limitApp\": \"default\",\n        \"strategy\": 0,\n        \"controlBehavior\": 0\n    },\n	{\n        \"resource\": \"xfglpt-school\",\n        \"count\": 300,\n        \"grade\": 1,\n        \"limitApp\": \"default\",\n        \"strategy\": 0,\n        \"controlBehavior\": 0\n    },\n	{\n        \"resource\": \"xfglpt-supplier\",\n        \"count\": 300,\n        \"grade\": 1,\n        \"limitApp\": \"default\",\n        \"strategy\": 0,\n        \"controlBehavior\": 0\n    }\n]', 'f44a27f5f1bceec2c87a0b5eb2c60297', '2025-03-25 00:33:33', '2025-04-23 00:00:06', 'nacos', '192.168.1.63', '', '5e3e155d-73b2-4a36-ab8b-e54454e8b351', '限流策略', '', '', 'json', '', '');
INSERT INTO `config_info` (`ID`, `DATA_ID`, `GROUP_ID`, `CONTENT`, `MD5`, `GMT_CREATE`, `GMT_MODIFIED`, `SRC_USER`, `SRC_IP`, `APP_NAME`, `TENANT_ID`, `C_DESC`, `C_USE`, `EFFECT`, `TYPE`, `C_SCHEMA`, `ENCRYPTED_DATA_KEY`) VALUES (28, 'application-prod.yml', 'DEFAULT_GROUP', 'spring:\n  autoconfigure:\n    exclude: com.alibaba.druid.spring.boot.autoconfigure.DruidDataSourceAutoConfigure\n\n# feign 配置\nfeign:\n  sentinel:\n    enabled: true\n  okhttp:\n    enabled: true\n  httpclient:\n    enabled: false\n  client:\n    config:\n      default:\n        connectTimeout: 10000\n        readTimeout: 10000\n  compression:\n    request:\n      enabled: true\n      min-request-size: 8192\n    response:\n      enabled: true\n\n# 暴露监控端点\nmanagement:\n  endpoints:\n    web:\n      exposure:\n        include: \'*\'\n\n# MyBatis Plus配置\nmybatis-plus:\n  # 不支持多包, 如有需要可在注解配置 或 提升扫包等级\n  mapperPackage: com.xfgl.**.*\n  # 对应的 XML 文件位置\n  mapperLocations: classpath*:mapper/**/*Mapper.xml\n  # 实体扫描，多个package用逗号或者分号分隔\n  typeAliasesPackage: com.xfgl.**.domain        \n  configuration:\n    # 自动驼峰命名规则（camel case）映射\n    mapUnderscoreToCamelCase: true\n    log-impl: org.apache.ibatis.logging.stdout.StdOutImpl\n    # 更详细的日志输出 会有性能损耗 org.apache.ibatis.logging.stdout.StdOutImpl\n    # 默认日志输出 org.apache.ibatis.logging.slf4j.Slf4jImpl\n  #    logImpl: org.apache.ibatis.logging.stdout.StdOutImpl\n  global-config:\n    # 是否打印 Logo banner\n    banner: false\n    dbConfig:\n      # 主键类型\n      # AUTO 自增 NONE 空 INPUT 用户输入 ASSIGN_ID 雪花 ASSIGN_UUID 唯一 UUID\n      idType: AUTO\n      logic-delete-field: delFlag # 全局逻辑删除的实体字段名\n      logic-delete-value: 1 # 逻辑已删除值(默认为 1)\n      logic-not-delete-value: 0 # 逻辑未删除值(默认为 0)\n', '49684a52b033f4fe188180c6be2a2f5c', '2025-03-27 23:44:40', '2025-03-27 23:44:40', 'nacos', '192.168.1.63', '', 'e7a3ac8d-49e9-4ae7-ac81-56ce1cc9ca10', '通用配置', NULL, NULL, 'yaml', NULL, '');
INSERT INTO `config_info` (`ID`, `DATA_ID`, `GROUP_ID`, `CONTENT`, `MD5`, `GMT_CREATE`, `GMT_MODIFIED`, `SRC_USER`, `SRC_IP`, `APP_NAME`, `TENANT_ID`, `C_DESC`, `C_USE`, `EFFECT`, `TYPE`, `C_SCHEMA`, `ENCRYPTED_DATA_KEY`) VALUES (29, 'xfglpt-gateway-prod.yml', 'DEFAULT_GROUP', 'spring:\n  redis:\n    host: 192.168.1.56\n    port: 6379\n    password: \n  cloud:\n    gateway:\n      discovery:\n        locator:\n          lowerCaseServiceId: true\n          enabled: true\n      routes:\n        # 认证中心\n        - id: xfglpt-auth\n          uri: lb://xfglpt-auth\n          predicates:\n            - Path=/auth/**\n          filters:\n            # 验证码处理\n            - CacheRequestFilter\n            - ValidateCodeFilter\n            - StripPrefix=1\n        # 代码生成\n        - id: xfglpt-gen\n          uri: lb://xfglpt-gen\n          predicates:\n            - Path=/code/**\n          filters:\n            - StripPrefix=1\n        # 定时任务\n        - id: xfglpt-job\n          uri: lb://xfglpt-job\n          predicates:\n            - Path=/schedule/**\n          filters:\n            - StripPrefix=1\n        # 系统模块\n        - id: xfglpt-system\n          uri: lb://xfglpt-system\n          predicates:\n            - Path=/system/**\n          filters:\n            - StripPrefix=1\n        # 文件服务\n        - id: xfglpt-file\n          uri: lb://xfglpt-file\n          predicates:\n            - Path=/file/**\n          filters:\n            - StripPrefix=1\n\n# 安全配置\nsecurity:\n  # 验证码\n  captcha:\n    enabled: true\n    type: math\n  # 防止XSS攻击\n  xss:\n    enabled: true\n    excludeUrls:\n      - /system/notice\n\n  # 不校验白名单\n  ignore:\n    whites:\n      - /auth/logout\n      - /auth/login\n      - /auth/register\n      - /*/v2/api-docs\n      - /*/v3/api-docs\n      - /csrf\n\n# springdoc配置\nspringdoc:\n  webjars:\n    # 访问前缀\n    prefix:\n', '64dd3eceb6ee22ae7cd7291a8c9ac8ea', '2025-03-27 23:44:40', '2025-03-27 23:44:40', 'nacos', '192.168.1.63', '', 'e7a3ac8d-49e9-4ae7-ac81-56ce1cc9ca10', '网关模块', NULL, NULL, 'yaml', NULL, '');
