INSERT INTO `his_config_info` (`ID`, `NID`, `DATA_ID`, `GROUP_ID`, `APP_NAME`, `CONTENT`, `MD5`, `GMT_CREATE`, `GMT_MODIFIED`, `SRC_USER`, `SRC_IP`, `OP_TYPE`, `TENANT_ID`, `ENCRYPTED_DATA_KEY`) VALUES (11, 198, 'xfglpt-gateway-dev.yml', 'DEFAULT_GROUP', '', 'spring:\n  redis:\n    host: 192.168.1.100\n    port: 6379\n    password: \n  cloud:\n    gateway:\n      tongweb:\n        httpclient:\n          connect-timeout: 45000\n          response-timeout: 45000s\n      discovery:\n        locator:\n          lowerCaseServiceId: true\n          enabled: true\n      routes:\n        # 认证中心\n        - id: xfglpt-auth\n          uri: lb://xfglpt-auth\n          predicates:\n            - Path=/auth/**\n          filters:\n            # 验证码处理\n            - CacheRequestFilter\n            - ValidateCodeFilter\n            - StripPrefix=1\n        # 代码生成\n        - id: xfglpt-gen\n          uri: lb://xfglpt-gen\n          predicates:\n            - Path=/code/**\n          filters:\n            - StripPrefix=1\n        # 定时任务\n        - id: xfglpt-job\n          uri: lb://xfglpt-job\n          predicates:\n            - Path=/schedule/**\n          filters:\n            - StripPrefix=1\n        # 系统模块\n        - id: xfglpt-system\n          uri: lb://xfglpt-system\n          predicates:\n            - Path=/system/**\n          filters:\n            - StripPrefix=1\n        # 文件服务\n        - id: xfglpt-file\n          uri: lb://xfglpt-file\n          predicates:\n            - Path=/file/**\n          filters:\n            - StripPrefix=1\n        # 学校服务\n        - id: xfglpt-school\n          uri: lb://xfglpt-school\n          predicates:\n            - Path=/school/**\n          filters:\n            - StripPrefix=1\n        # 学校服务\n        - id: xfglpt-supplier\n          uri: lb://xfglpt-supplier\n          predicates:\n            - Path=/supplier/**\n          filters:\n            - StripPrefix=1\n      globalcors:\n        corsConfigurations:\n          \'[/**]\':\n            allowedOriginPatterns: \"*\"\n            allowed-methods: \"*\"\n            allowed-headers: \"*\"\n            allow-credentials: true\n            exposedHeaders: \"Content-Disposition,Content-Type,Cache-Control\"\n\n\n\n# 安全配置\nsecurity:\n  # 验证码\n  captcha:\n    enabled: true\n    type: math\n  # 防止XSS攻击\n  xss:\n    enabled: true\n    excludeUrls:\n      - /system/notice\n      - /school/jzbuy/opinions/config\n      - /system/xfptnotice/**\n      - /school/jzbuy/opinions\n  # 不校验白名单\n  ignore:\n    whites:\n      - /auth/logout\n      - /auth/login\n      - /auth/register\n      - /*/v2/api-docs\n      - /*/v3/api-docs\n      - /csrf\n      - /system/open/**\n      - /school/question/config/content\n      - /school/questionnaireResult\n      - /school/questionnaireResult/selIpAddress\n      - /system/dict/data/type/**\n      - /school/school/open/**\n      - /school/team/meeting/importUserName\n      - /school/question/config/selectName\n      - /school/questionnaireSurvey/exportResultExcel\n      - /school/simOpen/redirecturi\n      - /system/sms/test\n      - /system/sms/sendSms\n      - /system/sms/smsLogin\n      - /system/user/resetPwdSendSms\n      - /system/sms/userEncrypt\n      - /school/suppliceContractSon/dateEnc\n      - /system/getRandom\n      - /system/verifyCertAndSign\n# springdoc配置\nspringdoc:\n  webjars:\n    # 访问前缀\n    prefix:\n', 'a7af1b3a9acc7b0dc0788b9c86bd2ce3', '2026-04-14 13:21:57', '2026-04-14 13:21:57', 'nacos', '192.168.1.110', 'U', '5e3e155d-73b2-4a36-ab8b-e54454e8b351', '');
