-- ----------------------------
-- Table structure for tenant_capacity
-- ----------------------------
DROP TABLE IF EXISTS `tenant_capacity`;
CREATE TABLE `tenant_capacity` (
  `ID` bigint NOT NULL,
  `TENANT_ID` varchar(512) NOT NULL DEFAULT '',
  `QUOTA` decimal(19,0) NOT NULL DEFAULT '0',
  `USAGE` decimal(19,0) NOT NULL DEFAULT '0',
  `MAX_SIZE` decimal(19,0) NOT NULL DEFAULT '0',
  `MAX_AGGR_COUNT` decimal(19,0) NOT NULL DEFAULT '0',
  `MAX_AGGR_SIZE` decimal(19,0) NOT NULL DEFAULT '0',
  `MAX_HISTORY_COUNT` decimal(19,0) NOT NULL DEFAULT '0',
  `GMT_CREATE` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `GMT_MODIFIED` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`ID`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='租户容量信息表';

-- ----------------------------
-- Records of tenant_capacity
-- ----------------------------
BEGIN;
COMMIT;

